import math

def calculate_order(a, n):
    # Calculate the order of a modulo n
    if math.gcd(a, n) != 1:
        return None # Should not happen here

    phi = n - 1
    factors = []
    temp = phi
    d = 2
    while d * d <= temp:
        if temp % d == 0:
            factors.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)

    order = phi
    for p in factors:
        new_order = order // p
        while new_order >= 1 and pow(a, new_order, n) == 1:
            order = new_order
            new_order //= p

    return order

# m = 197, a = 3
order_3_mod_197 = calculate_order(3, 197)

# C(197) = phi(197) / ord_197(3)
if order_3_mod_197 is not None:
    C_197 = 196 / order_3_mod_197
    print(f"Order of 3 mod 197: {order_3_mod_197}")
    print(f"Number of cycles C(197): {C_197}")
else:
    print("Error calculating order.")
